<script setup lang="ts">
import AdminPageDirectory from '../components/AdminPageDirectory.vue'
import AccountActions from '../components/AccountActions.vue'
import {computed,onBeforeUnmount,onMounted,reactive,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useApp} from '../stores/app'
import {backend} from '../services/backend'
import BackendLayout from '../components/BackendLayout.vue'
import ServiceFields from '../components/ServiceFields.vue'
import type {Field} from '../data/backendResources'
const route=useRoute(),router=useRouter(),app=useApp(),manager=computed(()=>route.path==='/admin-profile'||route.path.startsWith('/admin-app/')),base=computed(()=>manager.value?'/api/managers/me':'/api/customers/me'),profile=ref<Record<string,any>>({}),values=reactive<Record<string,any>>({}),passwords=reactive<Record<string,any>>({}),withdrawPassword=ref(''),devices=ref<any[]>([]),error=ref(''),message=ref(''),loading=ref(true),busy=ref(false)
const controller=new AbortController()
const fields=computed<Field[]>(()=>manager.value?[{key:'phone',label:'연락처',required:true},{key:'email',label:'이메일',type:'email',required:manager.value}]:[{key:'name',label:'이름',required:true},{key:'phone',label:'연락처',required:true},{key:'email',label:'이메일',type:'email',required:manager.value},{key:'emergency',label:'비상 연락처'},{key:'zipcode',label:'우편번호'},{key:'roadAddress',label:'도로명 주소'},{key:'detailAddress',label:'상세 주소'}])
async function load(){try{profile.value=await backend(base.value,{signal:controller.signal});for(const field of fields.value)values[field.key]=profile.value[field.key]||'';if(!manager.value)devices.value=await backend(base.value+'/device-tokens',{signal:controller.signal})}catch(e){if(!controller.signal.aborted)error.value=(e as Error).message}finally{loading.value=false}}
async function save(){await execute(async()=>{profile.value=await backend(base.value,{method:'PUT',body:Object.fromEntries(fields.value.map(field=>[field.key,values[field.key]||null]))});if(app.account)app.account={...app.account,name:profile.value.name};message.value='기본 정보를 저장했습니다.'})}
async function password(){await execute(async()=>{if(passwords.newPassword!==passwords.newPasswordConfirm)throw new Error('새 비밀번호 확인이 일치하지 않습니다.');await backend(base.value+'/password',{method:'PUT',body:passwords});for(const key of Object.keys(passwords))passwords[key]='';message.value='비밀번호를 변경했습니다.'})}
async function withdraw(){await execute(async()=>{await backend(base.value+'/withdraw',{method:'POST',body:{password:withdrawPassword.value}});app.clearAccount();await router.push(manager.value?'/admin-login':'/login')})}
async function execute(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load);onBeforeUnmount(()=>controller.abort())
</script>
<template><component :is="manager?BackendLayout:'div'"><section class="service-workspace account-service"><h1>{{manager?'관리자':'회원'}} 마이페이지</h1><p v-if="loading" role="status">정보를 불러오는 중입니다.</p><p v-if="error" class="service-error" role="alert">{{error}} <RouterLink :to="manager?'/admin-login':'/login'">로그인</RouterLink></p><p v-if="message" class="service-message" role="status">{{message}}</p><template v-if="profile.id"><section class="account-panel"><h2>내 정보</h2><p>{{profile.name}} · {{profile.loginId}}</p><template v-if="manager"><p>담당 지역: {{profile.regions?.map((region:any)=>region.name).join(' · ')||'미지정'}}</p><p>근무조: {{profile.shift?.name||'미지정'}} {{profile.shift?.startTime||''}}–{{profile.shift?.endTime||''}}</p><small>이름·담당 지역·근무조는 지정된 관리자 권한으로 변경됩니다.</small></template><form @submit.prevent="save"><ServiceFields :fields="fields" :values="values" :choices="{}" :disabled="busy"/><button :disabled="busy" type="submit">기본 정보 저장</button></form></section><section v-if="!manager" class="account-panel"><h2>비밀번호 변경</h2><form @submit.prevent="password"><label v-for="[key,label] in [['currentPassword','현재 비밀번호'],['newPassword','새 비밀번호'],['newPasswordConfirm','새 비밀번호 확인']]" :key="key">{{label}}<input v-model="passwords[key!]" type="password" :autocomplete="key==='currentPassword'?'current-password':'new-password'" required :disabled="busy"></label><button :disabled="busy" type="submit">비밀번호 변경</button></form></section><section v-if="!manager" class="account-panel"><h2>등록된 알림 기기</h2><p v-if="!devices.length">등록된 기기가 없습니다. 앱에서 알림을 허용하면 연결된 기기가 표시됩니다.</p><ul><li v-for="device in devices" :key="device.id">{{device.platform}} · {{device.active?'사용 중':'사용 중지'}}</li></ul><RouterLink to="/my-cars">내 차량 관리 →</RouterLink></section><details v-if="!manager" class="account-panel"><summary>회원 탈퇴</summary><p>탈퇴하면 계정과 연결된 정보를 더 이상 이용할 수 없습니다.</p><form @submit.prevent="withdraw"><label>본인 확인 비밀번호<input v-model="withdrawPassword" type="password" autocomplete="current-password" required></label><button :disabled="busy" type="submit">계정 탈퇴</button></form></details></template><AdminPageDirectory v-if="manager"/><AccountActions v-if="manager"/></section></component></template>
<style scoped>.account-service{max-width:1100px;margin:auto}.account-service h1{font-size:24px}.account-panel{padding:24px;border:1px solid var(--line);border-radius:10px;margin-bottom:20px;background:var(--surface)}.account-panel h2{font-size:18px;margin-top:0}.account-panel form{display:grid;gap:16px;margin-top:20px}.account-panel form>label{display:flex;flex-direction:column;gap:8px;max-width:500px}.account-panel form>button{justify-self:start}.account-panel small{color:#65748a}.account-panel summary{cursor:pointer}@media(max-width:600px){.account-panel{padding:16px}}</style>
